// OrderItemPK - composite primary key for the order_items table.
type OrderItemPK struct {
	OrderID   int64 `db:"order_id" json:"order_id"`
	ProductID int64 `db:"product_id" json:"product_id"`
}
type OrderItem struct {
	OrderID   int64 `db:"order_id" json:"order_id"`
	ProductID int64 `db:"product_id" json:"product_id"`
	Quantity  int64 `db:"quantity" json:"quantity"`
}

// OrderItemClient provides type-safe operations for the order_items table.
type OrderItemClient interface {
	// --- Read Operations ---

	// Get returns a single orderItem by primary key.
	Get(ctx context.Context, pk OrderItemPK, opts ...func(*CallOptions[OrderItemFieldOptions])) (*OrderItem, error)

	// GetMany returns order_items matching the given filter, field selection, and sort criteria.
	GetMany(ctx context.Context, input *GetOrderItemsInput, opts ...func(*CallOptions[OrderItemFieldOptions])) ([]*OrderItem, error)

	// Exists returns true if a orderItem with the given primary key exists.
	Exists(ctx context.Context, pk OrderItemPK, opts ...func(*CallOptions[OrderItemFieldOptions])) (bool, error)

	// ExistsWhere returns true if any orderItem matches the given filter.
	ExistsWhere(ctx context.Context, filter *OrderItemFilter, opts ...func(*CallOptions[OrderItemFieldOptions])) (bool, error)

	// Count returns the number of order_items matching the given filter.
	Count(ctx context.Context, filter *OrderItemFilter, opts ...func(*CallOptions[OrderItemFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new orderItem and returns the created entity.
	Create(ctx context.Context, input *CreateOrderItemInput, opts ...func(*CallOptions[OrderItemFieldOptions])) (*OrderItem, error)

	// CreateMany inserts multiple order_items in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreateOrderItemInput, opts ...func(*CallOptions[OrderItemFieldOptions])) ([]*OrderItem, error)

	// Update partially updates a orderItem by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, pk OrderItemPK, input *UpdateOrderItemInput, opts ...func(*CallOptions[OrderItemFieldOptions])) (*OrderItem, error)

	// UpdateMany updates multiple order_items and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdateOrderItemItem, opts ...func(*CallOptions[OrderItemFieldOptions])) ([]*OrderItem, error)

	// UpdateWhere updates all order_items matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *OrderItemFilter, input *UpdateOrderItemInput, opts ...func(*CallOptions[OrderItemFieldOptions])) ([]*OrderItem, error)

	// Upsert inserts a orderItem or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreateOrderItemInput, target OrderItemConflictTarget, opts ...func(*CallOptions[OrderItemFieldOptions])) (*OrderItem, error)

	// UpsertMany inserts or updates multiple order_items in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreateOrderItemInput, target OrderItemConflictTarget, opts ...func(*CallOptions[OrderItemFieldOptions])) ([]*OrderItem, error)

	// Increment atomically increments or decrements a numeric column on a orderItem.
	// Returns ErrNotFound if the primary key does not exist.
	Increment(ctx context.Context, pk OrderItemPK, input IncrementInput[OrderItemIncrementColumn], opts ...func(*CallOptions[OrderItemFieldOptions])) error

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a orderItem from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, pk OrderItemPK, opts ...func(*CallOptions[OrderItemFieldOptions])) error

	// HardDeleteMany permanently removes multiple order_items from the database.
	HardDeleteMany(ctx context.Context, pks []OrderItemPK, opts ...func(*CallOptions[OrderItemFieldOptions])) error

	// HardDeleteWhere permanently removes all order_items matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *OrderItemFilter, opts ...func(*CallOptions[OrderItemFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of order_items with total count for offset-based pagination.
	Paginate(ctx context.Context, input PaginateInput[OrderItemFilter], opts ...func(*CallOptions[OrderItemFieldOptions])) (*PaginateResult[OrderItem], error)

	// Connection returns a Relay-style cursor-paginated connection of order_items.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[OrderItemFilter], opts ...func(*CallOptions[OrderItemFieldOptions])) (*Connection[OrderItem], error)

	// Stream returns an iterator over order_items matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamOrderItemsInput, opts ...func(*CallOptions[StreamOrderItemFieldOptions])) iter.Seq2[*OrderItem, error]
}

